-- Frozen drama export manifests and managed artifacts. Manual after 121.
SET search_path TO new_design, public;
CREATE TABLE drama_export_manifests(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES drama_projects(id),variant text NOT NULL CHECK(variant IN('srt','timeline_json','project_markdown','project_json')),source_snapshot jsonb NOT NULL CHECK(jsonb_typeof(source_snapshot)='object'),source_hash char(64) NOT NULL CHECK(source_hash ~ '^[a-f0-9]{64}$'),request_key uuid NOT NULL UNIQUE,input_hash char(64) NOT NULL CHECK(input_hash ~ '^[a-f0-9]{64}$'),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE drama_export_artifacts(id uuid PRIMARY KEY,manifest_id uuid NOT NULL UNIQUE REFERENCES drama_export_manifests(id),storage_locator text NOT NULL CHECK(storage_locator ~ '^drama/[A-Za-z0-9._/-]+$' AND storage_locator !~ '(^|/)\.\.(/|$)|//'),display_filename text NOT NULL CHECK(display_filename !~ '[\\/]'),media_type text NOT NULL,checksum char(64) NOT NULL CHECK(checksum ~ '^[a-f0-9]{64}$'),byte_size bigint NOT NULL CHECK(byte_size>0),request_key uuid NOT NULL UNIQUE,input_hash char(64) NOT NULL CHECK(input_hash ~ '^[a-f0-9]{64}$'),created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER drama_export_manifests_immutable BEFORE UPDATE OR DELETE ON drama_export_manifests FOR EACH ROW EXECUTE FUNCTION guard_drama_history();CREATE TRIGGER drama_export_artifacts_immutable BEFORE UPDATE OR DELETE ON drama_export_artifacts FOR EACH ROW EXECUTE FUNCTION guard_drama_history();
